/** @jest-environment node */
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { parseProbe, planTranscode } from '../../../../../api/src/storage/video-transcode/transcode-profile';
import { buildNativeVideoItems } from '../../../../../api/src/screens/native-video-items';
import { readNativeVideoItems } from '../nativeZones';

test('a 30.303 fps source is prepared at 30 fps and the real descriptor producer and consumer admit its output', () => {
  // Real ffprobe output, generated by the commands recorded in the fixture.
  const probes = JSON.parse(readFileSync(join(__dirname, 'fixtures/rate-ceiling-probes.json'), 'utf8'));
  const source = parseProbe(probes.source);
  const output = parseProbe(probes.output);
  const outputBytes = Number(probes.output.format.size);
  expect(source.fps).toBeGreaterThan(30);
  const plan = planTranscode(source);
  expect(plan).toMatchObject({ action: 'transcode', required: true, issues: ['frame-rate'], plan: { fps: 30 } });
  expect(output.fps).toBe(30);

  const screenId = '11111111-1111-4111-8111-111111111111';
  const tenantId = '22222222-2222-4222-8222-222222222222';
  const assetId = '33333333-3333-4333-8333-333333333333';
  const url = 'https://bhdaxzfalaycfopvcopm.supabase.co/storage/v1/object/public/assets/test/rate.mp4';
  const sha256 = probes._meta.outputSha256;
  const asset = { id: assetId, fileUrl: url, fileHash: sha256, fileSize: outputBytes,
    processingMeta: { probe: { codec: output.videoCodec, rotation: output.rotation, pixFmt: output.pixFmt,
      fps: output.fps, codedWidth: output.width, codedHeight: output.height } } };
  const descriptor = buildNativeVideoItems({
    screen: { id: screenId, tenantId },
    manifest: { screenId, tenantId, isEmergency: false, sync: { enabled: false }, orientation: 'LANDSCAPE',
      playlists: [{ id: 'program', schedule: { mode: 'replace' }, items: [
        { item_id: 'clip', asset_id: assetId, url, asset_hash: sha256, asset_size: outputBytes, mime_type: 'video/mp4', muted: true },
        { item_id: 'image', asset_id: 'image', mime_type: 'image/png', muted: true },
      ] }] },
    assetById: id => id === assetId ? asset : null, assetByUrl: () => null,
  });
  expect(descriptor).not.toBeNull();
  expect(readNativeVideoItems(descriptor)?.items[0].asset.fps).toBe(30);
});
